import json

def main():
    daytona = Daytona()
    sandbox = daytona.create()
    print(f"Sandbox ID: {sandbox.id}")
    print(f"Sandbox state: {sandbox.state}")

    # Inspect sandbox object
    print(f"\nSandbox attributes:")
    for attr in dir(sandbox):
        if not attr.startswith('_'):
            try:
                val = getattr(sandbox, attr)
                if not callable(val):
                    print(f"  {attr}: {val}")
            except:
                pass

    # Check the process API client
    print(f"\nProcess API client host: {sandbox.process._api_client.configuration.host}")

if __name__ == "__main__":
    main()
